package com.gameaggregator.gameservice.application;import com.gameaggregator.platform.core.common.exception.NotFoundException;import com.gameaggregator.gameservice.api.GameDtos.*;import com.gameaggregator.gameservice.domain.*;import com.gameaggregator.gameservice.infrastructure.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service @Transactional public class GameService{final GameRepository games;final TaxonomyRepository taxonomies;final GameTaxonomyRepository links;public GameService(GameRepository g,TaxonomyRepository t,GameTaxonomyRepository l){games=g;taxonomies=t;links=l;}public Game create(Create r){return games.save(new Game(r.studioId(),r.publisherId(),r.slug(),r.title(),value(r.metadata()),r.visibility(),r.ageRating()));}public List<Game> list(){return games.findAll();}public Game get(UUID id){return games.findById(id).orElseThrow(()->new NotFoundException("GAME_NOT_FOUND","Game was not found"));}public Game update(UUID id,Update r){var g=get(id);g.title=r.title();g.metadata=value(r.metadata());g.visibility=r.visibility();g.ageRating=r.ageRating();g.status=r.status();return g;}public Game archive(UUID id){var g=get(id);g.status="ARCHIVED";return g;}public Taxonomy taxonomy(Classification r){return taxonomies.save(new Taxonomy(r.type(),r.code(),r.name()));}public List<Taxonomy> taxonomies(String type){return type==null?taxonomies.findAll():taxonomies.findAllByType(type);}public GameTaxonomy attach(UUID id,Attach r){get(id);if(!taxonomies.existsById(r.taxonomyId()))throw new NotFoundException("TAXONOMY_NOT_FOUND","Taxonomy was not found");return links.save(new GameTaxonomy(id,r.taxonomyId()));}private String value(String s){return s==null?"{}":s;}}